const q = $input.first().json.query || {};
if (q.token !== 'mercado-7d41c2a9e05b') return [{ json: { ok: false } }];
// últimos 12 meses + el actual
const d = new Date(Date.now() - 5 * 3600 * 1000);   // hora de Colombia
d.setUTCDate(1); d.setUTCMonth(d.getUTCMonth() - 11);
const desde = d.toISOString().slice(0, 10);
const consulta = {
  page_size: 100,
  filter: { and: [
    { property: 'Categoría', select: { equals: 'Salidas Ema' } },
    { property: 'Fecha', date: { on_or_after: desde } }
  ] },
  sorts: [{ property: 'Fecha', direction: 'ascending' }]
};
return [{ json: { ok: true, consulta: JSON.stringify(consulta) } }];

const movs = $('Movimientos de Ema').first().json.results || [];
const lugs = $input.first().json.results || [];
const txt = (a) => ((a || []).map(t => t.plain_text).join('') || '').trim();

// lugares (restaurantes y planes) por id
const info = {};
for (const l of lugs) {
  const pr = l.properties || {};
  info[l.id] = {
    id: l.id,
    nombre: txt(pr['Nombre'] && pr['Nombre'].title) || 'Lugar',
    puntuacion: pr['Puntuación'] && pr['Puntuación'].number != null ? pr['Puntuación'].number : null,
    notas: txt(pr['Notas'] && pr['Notas'].rich_text),
    clase: pr['Clase'] && pr['Clase'].select ? pr['Clase'].select.name : 'Restaurante'
  };
}

// salidas: una salida = un día con gastos de Salidas Ema
const por = {};            // mes → { mes, total, salidas: {fecha → {...}} }
const diaTotal = {};       // fecha → total de ese día
const lugarDias = {};      // lugarId → Set(fechas)
for (const p of movs) {
  const pr = p.properties || {};
  const f = pr['Fecha'] && pr['Fecha'].date && pr['Fecha'].date.start ? pr['Fecha'].date.start.slice(0, 10) : null;
  if (!f) continue;
  const monto = (pr['Monto'] && pr['Monto'].number) || 0;
  const concepto = txt(pr['Concepto'] && pr['Concepto'].title) || 'Gasto';
  const rel = pr['Restaurante'] && pr['Restaurante'].relation && pr['Restaurante'].relation[0] ? pr['Restaurante'].relation[0].id : null;
  const nomLugar = rel && info[rel] ? info[rel].nombre : null;
  const mes = f.slice(0, 7);
  const m = por[mes] || (por[mes] = { mes, veces: 0, total: 0, dias: [], salidas: {} });
  m.total += monto;
  const s = m.salidas[f] || (m.salidas[f] = { fecha: f, total: 0, gastos: [] });
  s.total += monto;
  s.gastos.push(nomLugar ? { c: concepto, m: monto, l: nomLugar } : { c: concepto, m: monto });
  diaTotal[f] = (diaTotal[f] || 0) + monto;
  if (rel) (lugarDias[rel] || (lugarDias[rel] = new Set())).add(f);
}
for (const m of Object.values(por)) {
  m.salidas = Object.values(m.salidas).sort((a, b) => a.fecha.localeCompare(b.fecha));
  m.dias = m.salidas.map(s => s.fecha);
  m.veces = m.salidas.length;
}
const meses = Object.values(por).sort((a, b) => a.mes.localeCompare(b.mes));

// lugares con Ema: los que aparecen en alguna salida, con cuánto cuesta una salida cuando van ahí
const lugares = Object.keys(lugarDias).map(id => {
  const dias = [...lugarDias[id]].sort();
  const costos = dias.map(d => diaTotal[d] || 0);
  const l = info[id] || { id, nombre: 'Lugar', puntuacion: null, notas: '', clase: 'Restaurante' };
  return { id, nombre: l.nombre, clase: l.clase, puntuacion: l.puntuacion, notas: l.notas, visitas: dias.length,
           promedio: Math.round(costos.reduce((a, b) => a + b, 0) / Math.max(1, costos.length)), ultima: dias[dias.length - 1] };
}).sort((a, b) => b.ultima.localeCompare(a.ultima));

// también los lugares de clase «Plan Ema» que aún no tienen salidas en estos 12 meses
for (const l of Object.values(info)) {
  if (l.clase === 'Plan Ema' && !lugares.find(x => x.id === l.id)) lugares.push({ id: l.id, nombre: l.nombre, clase: l.clase, puntuacion: l.puntuacion, notas: l.notas, visitas: 0, promedio: 0, ultima: null });
}
return [{ json: { meses, lugares } }];
